        return str(len(rows)) + ' ' + str(len(rows[0])) + '\n' + '\n'.join(rows)

    def rand_grid(r, c, p):
        return [''.join('1' if rng.random() < p else '0' for _ in range(c)) for _ in range(r)]

    tests = [
        fmt(['1']), fmt(['0']), fmt(['10', '01']), fmt(['11', '11']),
        fmt(['11000', '11001', '00100', '00011']),
        fmt(['1111', '1001', '1111']),
        fmt(['101010']), fmt(['1', '0', '1', '1']),
        fmt(['000', '000', '000']),
        fmt(['010', '111', '010']),
    ]
    for (r, c) in [(2, 3), (3, 3), (4, 5), (5, 5), (6, 8), (8, 6), (7, 7), (1, 12), (12, 1), (9, 9)]:
        for p in (0.35, 0.55):
            tests.append(fmt(rand_grid(r, c, p)))
    big_start = len(tests)
    R = C = 800
    snake = []
    for i in range(R):
        if i % 2 == 0:
            snake.append('1' * C)
        elif (i // 2) % 2 == 0:
            snake.append('0' * (C - 1) + '1')
